import 'dart:io';
import 'package:flutter/material.dart';
import '../../services/local_environment.dart';
class FilesPage extends StatefulWidget{const FilesPage({super.key});@override State<FilesPage> createState()=>_FilesPageState();}
class _FilesPageState extends State<FilesPage>{final e=LocalEnvironment.instance;List<FileSystemEntity> files=[];bool loading=true;@override void initState(){super.initState();_load();}Future<void> _load()async{await e.initialize();final list=await e.listFiles('');if(mounted)setState((){files=list;loading=false;});} @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Files'),actions:[IconButton(onPressed:_newFile,icon:const Icon(Icons.add))]),body:loading?const Center(child:CircularProgressIndicator()):ListView(children:files.map((f)=>ListTile(leading:Icon(f is Directory?Icons.folder_outlined:Icons.description_outlined),title:Text(f.uri.pathSegments.isEmpty?f.path:f.uri.pathSegments.last),subtitle:Text(f.path.replaceFirst('${e.root!.path}/','')),onTap:f is File?()=>_edit(f):null)).toList()));Future<void> _newFile()async{final name=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Create file'),content:TextField(controller:name,decoration:const InputDecoration(hintText:'example.html')),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Create'))]));if(ok==true){try{await e.createFile(name.text);await _load();}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x')));}}}Future<void> _edit(File file)async{final text=TextEditingController(text:await file.readAsString());if(!mounted)return;await showDialog<void>(context:context,builder:(c)=>AlertDialog(title:Text(file.uri.pathSegments.last),content:SizedBox(width:500,child:TextField(controller:text,minLines:10,maxLines:20,style:const TextStyle(fontFamily:'monospace'))),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Cancel')),FilledButton(onPressed:()async{await file.writeAsString(text.text);if(c.mounted)Navigator.pop(c);},child:const Text('Save'))]));}}
